export function generatedPlan(input){return {title:'TEST FIXTURE: Thirty-day plan',strategy:'TEST FIXTURE: Mix practical tips and product explanations for the approved audience. Draft dates require review.',warnings:['TEST FIXTURE: No performance evidence supplied.'],slots:Array.from({length:30},(_,i)=>({channel:input.preferences.channels[i%input.preferences.channels.length],planned_at:new Date(Date.parse(input.preferences.starts_on)+i*86400000+8*3600000).toISOString(),format:'static',brief:`TEST FIXTURE: ${i+1}. Explain ${input.brand.facts.find(f=>f.field==='offering')?.value??'the approved offering'} with a distinct practical angle.`,pillar:i%2?'Education':'Product',hook:`TEST FIXTURE hook ${i+1}`,cta:'Learn more',fact_ids:[input.brand.facts.find(f=>f.field==='offering')?.id??input.brand.facts[0].id]}))};}
export function modelResponse(value){return Response.json({object:'response',id:'resp_plan_fixture',status:'completed',output:[{type:'message',content:[{type:'output_text',text:JSON.stringify(value),annotations:[]}]}],usage:{input_tokens:100,output_tokens:100,total_tokens:200}});}
